# Generated by forge. Django REST framework views declare who may call them (run by
# .forge/check.sh with the project's own Python). Usage:
#   python drf_permissions.py <forge-tmp> [path...]
# When no tracked settings module sets REST_FRAMEWORK["DEFAULT_PERMISSION_CLASSES"] to
# something other than AllowAny (DRF's default is AllowAny), each APIView, generic view
# or viewset that subclasses a DRF class directly, and each @api_view function, must
# set permission_classes (or get_permissions / @permission_classes).
# Exit 0: nothing found; 1: findings printed; 3: cannot run ("skipped: ..." printed).
import ast
import re
import subprocess
import sys

DRF_MIXIN = re.compile(r"^(Create|List|Retrieve|Update|Destroy)ModelMixin$")
DRF_BASE = re.compile(r"^(APIView|GenericAPIView|(List|Create|Retrieve|Update|Destroy|ListCreate|RetrieveUpdate|RetrieveDestroy|RetrieveUpdateDestroy)APIView|ViewSet|GenericViewSet|ModelViewSet|ReadOnlyModelViewSet|ViewSetMixin)$")


def tracked_py():
    try:
        out = subprocess.run(["git", "ls-files", "*.py"], capture_output=True, text=True, check=True).stdout
    except Exception:
        return []
    return [p for p in out.splitlines() if p]


def parse(path):
    try:
        with open(path, encoding="utf-8") as f:
            src = f.read()
        return src, ast.parse(src, path)
    except (OSError, SyntaxError, ValueError):
        return None, None


def last_name(node):
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Subscript):
        return last_name(node.value)
    if isinstance(node, ast.Call):
        return last_name(node.func)
    return ""


def default_is_restricted():
    """True when a settings module sets DEFAULT_PERMISSION_CLASSES to something other than AllowAny."""
    for path in tracked_py():
        if "DEFAULT_PERMISSION_CLASSES" not in open(path, encoding="utf-8", errors="replace").read():
            continue
        _, tree = parse(path)
        if tree is None:
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.Dict):
                for k, v in zip(node.keys, node.values):
                    if isinstance(k, ast.Constant) and k.value == "DEFAULT_PERMISSION_CLASSES":
                        return restricted(v)
            if isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Subscript):
                key = node.targets[0].slice
                if isinstance(key, ast.Constant) and key.value == "DEFAULT_PERMISSION_CLASSES":
                    return restricted(node.value)
    return False


def restricted(value):
    if isinstance(value, (ast.List, ast.Tuple)):
        names = [e.value for e in value.elts if isinstance(e, ast.Constant) and isinstance(e.value, str)]
        if len(names) != len(value.elts):
            return True  # computed entries: assume the project knows
        return bool(names) and not any(n.endswith("AllowAny") for n in names)
    return True  # computed: not ours to judge


def findings_for(path):
    src, tree = parse(path)
    if tree is None or "rest_framework" not in src:
        return []
    out = []
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef):
            bases = [last_name(b) for b in node.bases]
            if not bases or not all(DRF_BASE.match(b) or DRF_MIXIN.match(b) for b in bases):
                continue
            if not any(DRF_BASE.match(b) for b in bases):
                continue
            declared = False
            for stmt in node.body:
                if isinstance(stmt, (ast.Assign, ast.AnnAssign)):
                    targets = stmt.targets if isinstance(stmt, ast.Assign) else [stmt.target]
                    if any(isinstance(t, ast.Name) and t.id == "permission_classes" for t in targets):
                        declared = True
                if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name == "get_permissions":
                    declared = True
            if not declared:
                out.append(f"{path}:{node.lineno} {node.name} sets no permission_classes, and no DEFAULT_PERMISSION_CLASSES other than AllowAny is set, so DRF lets anyone call it")
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            decos = [last_name(d) for d in node.decorator_list]
            if "api_view" in decos and "permission_classes" not in decos:
                out.append(f"{path}:{node.lineno} {node.name} (@api_view) has no @permission_classes, and no DEFAULT_PERMISSION_CLASSES other than AllowAny is set, so DRF lets anyone call it")
    return out


def main():
    paths = [p for p in sys.argv[2:] if p.endswith(".py")] or tracked_py()
    paths = [p for p in paths if not re.search(r"(^|/)(tests?/|test_[^/]*$|[^/]*_test\.py$|conftest\.py$|migrations/)", p)]
    if not paths or default_is_restricted():
        return 0
    found = [f for p in paths for f in findings_for(p)]
    for f in found:
        print(f)
    if found:
        print("Set permission_classes on the view (IsAuthenticated, or the project's permission), or a restrictive REST_FRAMEWORK DEFAULT_PERMISSION_CLASSES in settings; a public endpoint is the user's call")
    return 1 if found else 0


if __name__ == "__main__":
    sys.exit(main())
